<template><main class="admin-content"><AdminSalesWorkflow /><div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><p class="kc-eyebrow">Sales</p><h1 class="text-3xl font-black">Manual Quotes</h1><p class="text-slate-500">Create, send and manage customer quotations.</p></div><NuxtLink to="/admin/customers" class="btn-primary">Customers / New Quote</NuxtLink></div><section class="admin-panel grid gap-3 p-4 sm:grid-cols-[1fr_180px]"><input v-model="search" class="input" placeholder="Search quote or customer" @input="load"><select v-model="status" class="input" @change="load"><option value="all">All statuses</option><option v-for="x in ['draft','sent','accepted','declined','expired','converted']" :key="x" :value="x">{{x}}</option></select></section><section class="mt-5 space-y-3"><NuxtLink v-for="q in quotes" :key="q.id" :to="`/admin/manual-quotes/${q.id}`" class="admin-panel flex flex-wrap items-center justify-between gap-4 p-5 hover:border-blue-300"><div><div class="flex gap-2"><strong>{{q.quote_number}}</strong><span class="rounded-full bg-slate-100 px-2 py-1 text-xs font-bold capitalize">{{q.status}}</span></div><p>{{q.sales_customers?.company_name||q.sales_customers?.full_name}}</p><p class="text-sm text-slate-500">{{q.sales_customers?.email}}</p></div><div class="text-right"><strong class="text-lg">{{money(q.totals?.total)}}</strong><p class="text-xs text-slate-500">{{q.manual_quote_items?.length||0}} item(s)</p></div></NuxtLink><div v-if="!quotes.length" class="admin-panel p-8 text-center text-slate-500">No manual quotes yet.</div></section></main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch}=useAdminFetch();const quotes=ref<any[]>([]),search=ref(''),status=ref('all');const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));let t:any;function load(){clearTimeout(t);t=setTimeout(async()=>quotes.value=await adminFetch(`/api/admin/manual-quotes?search=${encodeURIComponent(search.value)}&status=${status.value}`) as any[],150)}onMounted(load)</script><style scoped>.input{@apply w-full rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm}.btn-primary{@apply rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-bold text-white}.admin-panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}</style>
